#!/usr/bin/env python3
"""Fetch Paul Graham essays and create an audiobook MP3."""

import html as html_lib
import os
import re
import shutil
import subprocess
import sys
import tempfile
from typing import List

import requests


def fetch_html(url: str) -> str:
    result = subprocess.run(["curl", "-Ls", url], capture_output=True, text=True)
    if result.returncode != 0 or not result.stdout:
        raise RuntimeError(f"Failed to fetch {url}: {result.stderr.strip()}")
    return result.stdout


def html_to_text(html: str) -> str:
    html = re.sub(r"(?is)<script.*?>.*?</script>", " ", html)
    html = re.sub(r"(?is)<style.*?>.*?</style>", " ", html)
    html = re.sub(r"(?i)<br\s*/?>", "\n", html)
    html = re.sub(r"(?i)</p\s*>", "\n", html)
    html = re.sub(r"(?i)<p\s*>", "", html)
    text = re.sub(r"(?s)<[^>]+>", " ", html)
    text = html_lib.unescape(text)
    text = text.replace("\r", "\n")

    lines = [line.strip() for line in text.split("\n")]
    cleaned_lines = []
    for line in lines:
        if not line:
            continue
        lower = line.lower()
        if lower in ("image",):
            continue
        if "want to start a startup" in lower:
            continue
        if "get funded by y combinator" in lower:
            continue
        cleaned_lines.append(line)

    text = "\n".join(cleaned_lines)
    text = re.sub(r"[ \t]+", " ", text)
    return text.strip()


def verify_content(text: str, expected_min_chars: int = 1000) -> bool:
    if len(text) < expected_min_chars:
        print(f"WARNING: Content may be truncated ({len(text)} chars)")
        return False
    head = text[:500].lower()
    if "summary" in head or "key points" in head:
        print("WARNING: Content appears to be a summary, not full text")
        return False
    return True


def clean_text_for_tts(text: str) -> str:
    text = re.sub(r"http[s]?://\S+", "", text)
    text = re.sub(r"\[\d+\]", "", text)
    text = re.sub(r"\s+", " ", text)
    text = re.sub(r"[^\w\s\.,!?;:\'\"()\-]", "", text)
    return text.strip()


def chunk_text(text: str, max_chars: int = 4000) -> List[str]:
    sentences = re.split(r"(?<=[.!?])\s+", text)
    chunks = []
    current = ""
    for sentence in sentences:
        if len(current) + len(sentence) + 1 <= max_chars:
            current += sentence + " "
        else:
            if current:
                chunks.append(current.strip())
            current = sentence + " "
    if current:
        chunks.append(current.strip())
    return chunks


def concatenate_audio(audio_files: List[str], output_path: str) -> bool:
    if not audio_files:
        return False
    list_file = "/tmp/audio_list.txt"
    with open(list_file, "w", encoding="utf-8") as f:
        for audio_file in audio_files:
            f.write(f"file '{audio_file}'\n")

    result = subprocess.run(
        ["ffmpeg", "-y", "-f", "concat", "-safe", "0", "-i", list_file, "-c", "copy", output_path],
        capture_output=True,
        text=True,
    )

    for fpath in audio_files:
        try:
            os.unlink(fpath)
        except FileNotFoundError:
            pass
    try:
        os.unlink(list_file)
    except FileNotFoundError:
        pass

    if result.returncode != 0:
        print(result.stderr)
        return False
    return True


def create_with_elevenlabs(text: str, output_path: str) -> bool:
    api_key = os.environ.get("ELEVENLABS_API_KEY")
    if not api_key:
        return False

    voice_id = "21m00Tcm4TlvDq8ikWAM"  # Rachel
    chunks = chunk_text(text, max_chars=4500)
    audio_files = []

    temp_dir = tempfile.mkdtemp(prefix="tts_chunks_")
    try:
        for i, chunk in enumerate(chunks):
            chunk_file = os.path.join(temp_dir, f"chunk_{i:03d}.mp3")
            response = requests.post(
                f"https://api.elevenlabs.io/v1/text-to-speech/{voice_id}",
                headers={
                    "xi-api-key": api_key,
                    "Content-Type": "application/json",
                },
                json={
                    "text": chunk,
                    "model_id": "eleven_turbo_v2_5",
                    "voice_settings": {"stability": 0.5, "similarity_boost": 0.75},
                },
                timeout=60,
            )
            if response.status_code != 200:
                print(f"ElevenLabs error {response.status_code}: {response.text}")
                return False
            with open(chunk_file, "wb") as f:
                f.write(response.content)
            audio_files.append(chunk_file)

        return concatenate_audio(audio_files, output_path)
    finally:
        shutil.rmtree(temp_dir, ignore_errors=True)


def create_with_openai(text: str, output_path: str) -> bool:
    api_key = os.environ.get("OPENAI_API_KEY")
    if not api_key:
        return False

    chunks = chunk_text(text, max_chars=4000)
    audio_files = []

    temp_dir = tempfile.mkdtemp(prefix="tts_chunks_")
    try:
        for i, chunk in enumerate(chunks):
            chunk_file = os.path.join(temp_dir, f"chunk_{i:03d}.mp3")
            response = requests.post(
                "https://api.openai.com/v1/audio/speech",
                headers={
                    "Authorization": f"Bearer {api_key}",
                    "Content-Type": "application/json",
                },
                json={
                    "model": "tts-1",
                    "input": chunk,
                    "voice": "onyx",
                    "response_format": "mp3",
                },
                timeout=60,
            )
            if response.status_code != 200:
                print(f"OpenAI TTS error {response.status_code}: {response.text}")
                return False
            with open(chunk_file, "wb") as f:
                f.write(response.content)
            audio_files.append(chunk_file)

        return concatenate_audio(audio_files, output_path)
    finally:
        shutil.rmtree(temp_dir, ignore_errors=True)


def create_with_gtts(text: str, output_path: str) -> bool:
    try:
        from gtts import gTTS
    except Exception as exc:
        print(f"gTTS not available: {exc}")
        return False

    chunks = chunk_text(text, max_chars=4500)
    audio_files = []

    temp_dir = tempfile.mkdtemp(prefix="tts_chunks_")
    try:
        for i, chunk in enumerate(chunks):
            chunk_file = os.path.join(temp_dir, f"chunk_{i:03d}.mp3")
            tts = gTTS(text=chunk, lang="en", slow=False)
            tts.save(chunk_file)
            audio_files.append(chunk_file)

        return concatenate_audio(audio_files, output_path)
    finally:
        shutil.rmtree(temp_dir, ignore_errors=True)


def create_audiobook(text: str, output_path: str) -> bool:
    has_elevenlabs = bool(os.environ.get("ELEVENLABS_API_KEY"))
    has_openai = bool(os.environ.get("OPENAI_API_KEY"))

    if has_elevenlabs:
        print("Using ElevenLabs TTS")
        if create_with_elevenlabs(text, output_path):
            return True
        print("Falling back from ElevenLabs...")

    if has_openai:
        print("Using OpenAI TTS")
        if create_with_openai(text, output_path):
            return True
        print("Falling back from OpenAI...")

    print("Using gTTS fallback")
    return create_with_gtts(text, output_path)


def strip_leading_title_and_date(text: str, title: str) -> str:
    lines = [line.strip() for line in text.split("\n") if line.strip()]
    if lines and lines[0].lower() == title.lower():
        lines.pop(0)
    if lines and lines[0].lower() == "paul graham":
        lines.pop(0)
    if lines and re.match(r"^[A-Za-z]+\s+\d{4}$", lines[0]):
        lines.pop(0)
    return " ".join(lines)


def main() -> int:
    essays = [
        ("https://www.paulgraham.com/ds.html", "Do Things that Don't Scale"),
        ("https://www.paulgraham.com/foundermode.html", "Founder Mode"),
    ]

    sections = []
    for url, title in essays:
        print(f"Fetching: {title}")
        html = fetch_html(url)
        text = html_to_text(html)
        verify_content(text)
        text = strip_leading_title_and_date(text, title)
        sections.append(f"Essay: {title}. {text}")

    all_text = "Paul Graham Essays. " + " ".join(sections)
    clean_text = clean_text_for_tts(all_text)
    print(f"Total text length: {len(clean_text)} characters")

    output_path = "/root/audiobook.mp3"
    success = create_audiobook(clean_text, output_path)
    if not success:
        print("Failed to create audiobook")
        return 1

    print(f"Audiobook created: {output_path}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
